	private static final Object SUMMARY_KEY = new Object();

	private LmdbNativeRuntimePlan() {
	}

	static Invocation begin(TupleExpr target, SlotPlan entryPlan, NativeSlotLayout layout, long initialBoundMask) {
		if (target == null || !target.isRuntimeTelemetryEnabled()) {
			return null;
		}
		Summary summary;
		synchronized (target) {
			summary = target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN) == null
					? null
					: (Summary) target.getQueryModelMetadata(SUMMARY_KEY);
			if (summary == null) {
				summary = new Summary(target);
				target.setQueryModelMetadata(SUMMARY_KEY, summary);
			}
		}
		Invocation invocation = summary.begin(entryPlan, layout.slotNames(), initialBoundMask);
		summary.publish();
		return invocation;
	}

	static String planned(String kind, String plan) {
		StringBuilder out = new StringBuilder("LMDB native physical plan (planned)\n")
				.append("  kind: ")
				.append(kind)
				.append("\n  plan:\n");
		appendIndented(out, plan, "    ");
		return out.toString();
	}

	private static void appendIndented(StringBuilder out, String text, String indent) {
		String[] lines = text.split("\\R", -1);
		for (int i = 0; i < lines.length; i++) {
			if (i > 0) {
				out.append('\n');
			}
			out.append(indent).append(lines[i]);
		}
	}

	private static final class Summary {
		private final TupleExpr target;
		private final List<Invocation> invocations = new ArrayList<>();

		private Summary(TupleExpr target) {
			this.target = target;
		}

		private synchronized Invocation begin(SlotPlan entryPlan, String[] slotNames, long initialBoundMask) {
			Invocation invocation = new Invocation(this, invocations.size(), entryPlan, slotNames, initialBoundMask);
			invocations.add(invocation);
			return invocation;
		}

		private synchronized void publish() {
			String rendered = render();
			target.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, rendered);
			if (target instanceof QueryRoot) {
				TupleExpr arg = ((QueryRoot) target).getArg();
				synchronized (arg) {
					arg.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, rendered);
				}
			}
		}

		private String render() {
			StringBuilder out = new StringBuilder("LMDB native physical plan (executed)");
			for (Invocation invocation : invocations) {
				invocation.render(out);
			}
			return out.toString();
		}
	}

