			ArrayList<String> rendered = new ArrayList<>(order.length);
			for (SlotPlan child : order) {
				rendered.add(LmdbNativeExplain.describe(child, slotNames, initialBoundMask));
			}
			actualOrder = List.copyOf(rendered);
