				out.append("\n          predicate: ");
				appendTerm(out, pred);
				out.append("\n          object: ");
				appendTerm(out, obj);
				out.append("\n          context: ");
				appendTerm(out, context);
				out.append("\n          bindingValues: ")
						.append(count == 1L ? "exact" : "representative (aggregated by bound/unbound shape)");
				out.append("\n          opens: ").append(count);
